<!doctype html><html><body style="margin:0;background:#f7f1eb;font-family:Arial,sans-serif;color:#342d29"><table role="presentation" width="100%"><tr><td align="center" style="padding:32px"><table role="presentation" width="600" style="max-width:100%;background:#fffdfc;border-radius:20px;overflow:hidden"><tr><td align="center" style="padding:28px"><img src="<?=config('app.url').asset('images/logo-smilebaby.png')?>" width="190" alt="SmileBaby"></td></tr><tr><td style="padding:0 36px 36px"><h1 style="font-family:Georgia,serif;color:#342d29">Comanda ta a fost primită.</h1><p>Bună, <?=e($customer['first_name'])?>! Pregătim cu grijă comanda <strong><?=e($order['order_number'])?></strong>.</p><?php if(($customer['customer_type']??'individual')==='company'):?><p style="padding:14px 16px;background:#f7eee6;border-radius:12px"><strong>Facturare persoană juridică</strong><br><?=e($customer['company_name'])?> · CUI/CIF <?=e($customer['company_vat_id'])?><br><?=e($customer['company_registration_number'])?> · <?=e($customer['company_address'])?></p><?php endif?><table width="100%" style="border-collapse:collapse;margin:24px 0"><?php foreach($order['items'] as $item):?><tr><td style="padding:12px 0;border-bottom:1px solid #eadbcd"><?=e($item['product']['name'])?> × <?=$item['quantity']?><?php if(!empty($item['customization']['values'])):?><small style="display:block;margin-top:6px;color:#8b654b">Personalizare: <?php foreach($item['customization']['values'] as $index=>$detail):?><?=$index?' · ':''?><?=e($detail['label'])?>: <?=e($detail['value'])?><?php endforeach?></small><?php endif?><?php if(!empty($item['addons'])):?><span style="display:block;margin-top:8px;padding:8px 10px;border-left:3px solid #a87859;background:#faf2eb;color:#674838;font-size:12px"><strong>＋ Completează setul</strong><?php foreach($item['addons'] as $addon):?><small style="display:block;margin-top:4px"><?=e($addon['name'])?> — <?= (int)$addon['quantity'] ?> × <?=money($addon['price'])?></small><?php endforeach?></span><?php endif?></td><td align="right" style="border-bottom:1px solid #eadbcd"><?=money($item['total'])?></td></tr><?php endforeach?><tr><td style="padding-top:16px"><strong>Total</strong></td><td align="right" style="padding-top:16px"><strong><?=money($order['total'])?></strong></td></tr></table><p><strong>Metoda de plată:</strong> <?=e($order['payment_method_label'])?> — <?=e($order['payment_status'])?></p><p><a href="<?=config('app.url')?>/urmareste-comanda" style="display:inline-block;background:#8b654b;color:#fff;text-decoration:none;padding:14px 22px;border-radius:999px">VEZI COMANDA</a></p></td></tr></table></td></tr></table></body></html>
